// Full refresh over a trailing window rather than incremental. Attendance
// gets corrected days after the fact, and a window wide enough to pick that
// up beats an incremental sync that quietly misses it.

const body = $input.first().json;
const agentRows = $('Agent-booked appointment ids').all();
const agentIds = new Set(agentRows.map(r => String(r.json.appointment_id)));

const bookings = Array.isArray(body) ? body : (body.bookings || body.data || []);
if (!Array.isArray(bookings)) {
  return [{ json: { rows: [], fetched: 0, error: 'unreadable calendar response' } }];
}

const STATUS = {
  accepted: 'booked',
  pending: 'booked',
  confirmed: 'confirmed',
  attended: 'attended',
  completed: 'attended',
  noshow: 'no_show',
  no_show: 'no_show',
  cancelled: 'cancelled',
  rejected: 'cancelled'
};

const rows = bookings.map(b => {
  const raw = String(b.status || b.outcome || '').toLowerCase().replace(/[^a-z_]/g, '');
  const starts = b.startTime || b.start || b.starts_at;
  const id = String(b.uid || b.id || '');
  if (!id || !starts) return null;
  const past = new Date(starts) < new Date();
  return {
    appointment_id: id,
    booked_at: b.createdAt || b.booked_at || starts,
    starts_at: starts,
    status: STATUS[raw] || (past ? 'booked' : 'booked'),
    status_at: b.updatedAt || b.updated_at || null,
    booked_by: agentIds.has(id) ? 'agent' : 'human'
  };
}).filter(Boolean);

return [{ json: { rows, fetched: bookings.length } }];

// One morning line, built to be read on a phone. The show-rate split is
// published whether it flatters the agent or not -- that is the rule.

const outcomes = $('Yesterday\'s call outcomes').first().json;
const rates = $('Show rate by booker').all().map(r => r.json);

const hasOutcomes = outcomes && outcomes.day !== undefined && outcomes.day !== null;
const dayLine = hasOutcomes
  ? '*Yesterday* — ' + outcomes.calls + ' calls · ' + outcomes.booked + ' booked · ' +
    outcomes.escalated + ' escalated · ' + outcomes.containment_pct + '% contained' +
    (outcomes.cost_per_booking_usd ? ' · $' + Number(outcomes.cost_per_booking_usd).toFixed(2) + '/booking' : '')
  : '*Yesterday* — no call data recorded (broken integration or a quiet day)'; 

const rateLine = rates.length
  ? rates.map(r => {
      const pct = r.show_rate_pct === null ? 'no resolved appointments' : Number(r.show_rate_pct).toFixed(1) + '%';
      return '• *' + r.booked_by + '*-booked: ' + r.attended + '/' + r.appointments + ' attended (' + pct + ')';
    }).join('\n')
  : '• No past appointments on record yet';

return [{
  json: {
    text: '🌅 *Frontdesk morning summary*\n\n' + dayLine + '\n\n*Show rate (past appointments)*\n' + rateLine
  }
}];
